test('binary INTEGER expression casts read fresh cached values after writes', async () => {
  const { db, conn } = await connect()
  const fixtures: [string, unknown[][], unknown[], [string | null, unknown[][], unknown[], unknown[]][]][] = [
    ["SELECT CAST(CONCAT(b) AS SIGNED) AS x FROM t ORDER BY id LIMIT ? OFFSET ?",[["x",8,21,128,0,63,"","","",""]],[],[["",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ''"}]],["20",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ' '"}]],["090A0D",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x09\\x0A\\x0D'"}]],["80",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x80'"}]],["0041",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x00A'"}]],["C3A9",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\xC3\\xA9'"}]],["317879",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1xy'"}]],["3178",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1x'"}]],["414141414141",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: 'AAAAAA'"}]],[null,[[null]],[{"x":null}],[]]]],
    ["SELECT CAST(b COLLATE `binary` AS SIGNED) AS x FROM t ORDER BY id LIMIT ? OFFSET ?",[["x",8,21,128,0,63,"","","",""]],[],[["",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ''"}]],["20",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ' '"}]],["090A0D",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x09\\x0A\\x0D'"}]],["80",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x80'"}]],["0041",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x00A'"}]],["C3A9",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\xC3\\xA9'"}]],["317879",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1xy'"}]],["3178",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1x'"}]],["414141414141",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: 'AAAAAA'"}]],[null,[[null]],[{"x":null}],[]]]],
    ["SELECT CAST(CAST(b AS BINARY) AS SIGNED) AS x FROM t ORDER BY id LIMIT ? OFFSET ?",[["x",8,21,128,0,63,"","","",""]],[],[["",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ''"}]],["20",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: ' '"}]],["090A0D",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x09\\x0A\\x0D'"}]],["80",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x80'"}]],["0041",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\x00A'"}]],["C3A9",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '\\xC3\\xA9'"}]],["317879",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1xy'"}]],["3178",[[1]],[{"x":1}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: '1x'"}]],["414141414141",[[0]],[{"x":0}],[{"Level":"Warning","Code":1292,"Message":"Truncated incorrect INTEGER value: 'AAAAAA'"}]],[null,[[null]],[{"x":null}],[]]]],
  ]
  try {
    await conn.query('CREATE DATABASE integer_expression_fresh')
    await conn.query('USE integer_expression_fresh')
    await conn.query('CREATE TABLE t(id INT PRIMARY KEY,b VARBINARY(1024))')
    await conn.query("INSERT INTO t VALUES(1,X'31'),(2,X'31'),(3,NULL)")
    for (const [sql, expectedFields, prepareWarnings, writes] of fixtures) {
      const options = { sql, rowsAsArray: true }
      const statement = await conn.prepare(options)
      try {
        const prepared = statement as unknown as { statement: { columns: mysql.FieldPacket[] } }
        assert.deepEqual(fields(prepared.statement.columns), expectedFields, 'prepare: ' + sql)
        assert.deepEqual((await conn.query('SHOW WARNINGS'))[0], prepareWarnings, 'prepare warnings: ' + sql)
        for (const [hex, expectedRows, expectedObjects, warnings] of writes) {
          await conn.query('UPDATE t SET b=? WHERE id=2', [hex === null ? null : Buffer.from(hex, 'hex')])
          for (const method of ['query', 'execute', 'statement'] as const) {
            const [actual, columns] = method === 'statement' ? await statement.execute([1,1]) : method === 'query' ? await conn.query(options, [1,1]) : await conn.execute(options, [1,1])
            assert.deepEqual(actual, method === 'statement' ? expectedObjects : expectedRows, method + ': rows: ' + sql)
            assert.deepEqual(fields(columns), expectedFields, method + ': fields: ' + sql)
            assert.deepEqual((await conn.query('SHOW WARNINGS'))[0], warnings, method + ': warnings: ' + sql)
          }
        }
      } finally {
        await statement.close()
        conn.unprepare(options)
      }
    }
  } finally {
    await conn.query('DROP DATABASE integer_expression_fresh')
    await conn.end()
    await db?.end()
  }
})
